import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec3, vec4, uniform, mix, float, clamp } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-card-0-thumbnail';
  group.position.set(2.5, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 1.0;
  const captionHeight = 0.22;

  // --- Image plane ---
  const imgTex = ctx.textureLoader.load('/prism-mock/home/nodes/cta-hero-isolated.png');
  imgTex.colorSpace = THREE.SRGBColorSpace;

  const hoverLift = uniform(0.0);
  const focusAmount = uniform(0.0);

  const imgGeo = new THREE.PlaneGeometry(width, height - captionHeight);
  const imgMat = new THREE.MeshBasicNodeMaterial();
  imgMat.colorNode = texture(imgTex, uv());
  imgMat.transparent = true;

  const imgMesh = new THREE.Mesh(imgGeo, imgMat);
  imgMesh.position.set(0, captionHeight / 2, 0);
  group.add(imgMesh);

  // --- Caption strip ---
  const inkColor = new THREE.Color('#16161d');
  const accentColor = new THREE.Color('#ff2a38');

  const stripGeo = new THREE.PlaneGeometry(width, captionHeight);
  const stripMat = new THREE.MeshBasicNodeMaterial();
  const stripUv = uv();
  const edgeMask = clamp(float(1.0).sub(stripUv.x.mul(20.0).clamp(0.0, 1.0)), 0.0, 1.0);
  stripMat.colorNode = mix(
    vec3(inkColor.r, inkColor.g, inkColor.b),
    vec3(accentColor.r, accentColor.g, accentColor.b),
    edgeMask.mul(focusAmount)
  );
  const stripMesh = new THREE.Mesh(stripGeo, stripMat);
  stripMesh.position.set(0, -(height / 2) + captionHeight / 2, 0.001);
  group.add(stripMesh);

  // --- Accent edge frame (focus indicator) ---
  const edgeGeo = new THREE.PlaneGeometry(width + 0.03, height + 0.03);
  const edgeMat = new THREE.MeshBasicNodeMaterial();
  edgeMat.transparent = true;
  edgeMat.colorNode = vec4(accentColor.r, accentColor.g, accentColor.b, focusAmount.mul(0.6));
  const edgeMesh = new THREE.Mesh(edgeGeo, edgeMat);
  edgeMesh.position.set(0, 0, -0.001);
  group.add(edgeMesh);

  // Base Y position for hover lift animation
  const baseY = group.position.y;

  let hoverTween = null;
  let pressTween = null;

  function onHoverStart() {
    if (hoverTween) hoverTween.kill();
    focusAmount.value = 1.0;
    hoverTween = gsap.timeline();
    hoverTween.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    }, 0);
  }

  function onHoverEnd() {
    if (hoverTween) hoverTween.kill();
    focusAmount.value = 0.0;
    hoverTween = gsap.timeline();
    hoverTween.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out'
    }, 0);
  }

  function onClick() {
    if (pressTween) pressTween.kill();
    pressTween = gsap.timeline();
    pressTween.to(group.scale, {
      x: 0.97, y: 0.97, z: 0.97,
      duration: 0.12,
      ease: 'back.out'
    }).to(group.scale, {
      x: 1, y: 1, z: 1,
      duration: 0.12,
      ease: 'back.out'
    });

    if (group.userData.eventBus && typeof group.userData.eventBus.emit === 'function') {
      group.userData.eventBus.emit('hub-journal.select');
    }
    group.dispatchEvent({ type: 'hub-journal.select' });
  }

  group.userData.handlers = {
    onHoverStart,
    onHoverEnd,
    onClick,
    onPointerOver: onHoverStart,
    onPointerOut: onHoverEnd,
    onPointerDown: onClick
  };

  group.userData.cleanup = function cleanup() {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    imgGeo.dispose();
    imgMat.dispose();
    stripGeo.dispose();
    stripMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    if (imgTex && imgTex.dispose) imgTex.dispose();
  };

  return group;
}
